def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        base = DAILY_SALARY * 0.25
        if hp <= 3 or no_water_days >= 1:
            base = DAILY_SALARY * 0.55
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    strong_prev = []
    weak_prev = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            bid = float(prev['bid'])
            prev_bids.append(bid)
            if opp.get('budget', 0) >= 200:
                strong_prev.append(bid)
            else:
                weak_prev.append(bid)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    strong_high = max(strong_prev) if strong_prev else highest_prev
    weak_high = max(weak_prev) if weak_prev else 0.0

    alive_count = len(alive) + 1
    pressure = alive_count * WATER_REQ - supply

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if pressure >= WATER_REQ * 2:
        urgency += 2
    elif pressure > 0:
        urgency += 1

    if day >= 8:
        urgency += 1

    if supply >= 24:
        bid = DAILY_SALARY * 0.22
    elif supply >= 21:
        bid = DAILY_SALARY * 0.35
    elif supply >= 18:
        bid = DAILY_SALARY * 0.5
    else:
        bid = DAILY_SALARY * 0.68

    if prev_bids:
        if urgency >= 5:
            target = max(DAILY_SALARY * 0.92, strong_high + 1.0)
            bid = max(bid, target)
        elif urgency >= 3:
            target = max(DAILY_SALARY * 0.72, min(strong_high + 0.75, DAILY_SALARY * 0.95))
            bid = max(bid, target)
        elif pressure > 0:
            target = max(DAILY_SALARY * 0.48, min(weak_high + 0.5, DAILY_SALARY * 0.7))
            bid = max(bid, target)
        else:
            bid = max(bid, min(DAILY_SALARY * 0.42, highest_prev * 0.45 if highest_prev > 0 else DAILY_SALARY * 0.3))

    if hp >= 8 and no_water_days == 0 and supply >= 21:
        bid = min(bid, DAILY_SALARY * 0.38)

    reserve = 0.0
    if hp <= 4 or no_water_days >= 1:
        reserve = 0.0
    elif day <= 3:
        reserve = DAILY_SALARY * 2.0
    else:
        reserve = DAILY_SALARY * 1.0

    affordable = max(0.0, budget - reserve)
    if urgency >= 5:
        affordable = budget
    elif affordable <= 0:
        affordable = min(budget, DAILY_SALARY * 0.45)

    bid = min(bid, affordable, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    # Alive opponents and yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4)

    high_prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            high_prev_bids.append(float(bid))

    max_prev_bid = max(high_prev_bids) if high_prev_bids else 0.0

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Supply pressure heuristic: when supply is close to MAX, fewer players need to bid extremely.
    # Convert supply to an integer bucket safely.
    supply_int = int(round(supply))
    # Expected maximum number of WATER_REQ units available (approx)
    units = max(0, int(supply_int // WATER_REQ))

    # Base aggressiveness: if we're low HP or have accumulated no-water days, bid more.
    urgent = (hp <= 2.5) or (no_water_days >= 2)

    # If opponents were bidding high yesterday, we shade slightly under their max to avoid price inflation.
    # But ensure bid is competitive when urgent.
    if max_prev_bid >= DAILY_SALARY * 0.85:
        if urgent:
            target = max_prev_bid * 0.65 + 15.0
        else:
            target = max_prev_bid * 0.55 + 10.0
    else:
        if urgent:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.45

    # If supply is tight (few units), increase bid to secure water.
    if units <= 1:
        target *= 1.15
    elif units >= 2:
        target *= 0.95

    # Never exceed a fraction of budget; also cap relative to salary to keep sustainable.
    cap = DAILY_SALARY * (0.95 if urgent else 0.65)
    bid = min(budget, cap, target)

    # Ensure non-negative bid
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    my_bid = 0.0

    # Given supply range (15-25) and WATER_REQ (13), typically only one agent
    # can get their full water requirement, making it a winner-take-all scenario.

    # Scenario 1: Critical survival mode (low HP or missed water yesterday)
    if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
        # Bid very aggressively to ensure water, potentially exceeding daily salary.
        if highest_prev_bid > DAILY_SALARY * 0.8:
            my_bid = highest_prev_bid + 5.0
        else:
            my_bid = DAILY_SALARY * 1.05 # Bid slightly above salary

    # Scenario 2: Normal operation (HP is good)
    else:
        # Base bid is competitive, reflecting the high competition for water.
        base_competitive_bid = DAILY_SALARY * 0.75 # 112.5

        if highest_prev_bid > 0:
            # Bid slightly above the highest previous bid to win, but not excessively.
            my_bid = max(base_competitive_bid, highest_prev_bid + 1.5)
        else:
            # If no previous bids (e.g., Day 1), start with a strong competitive bid.
            my_bid = base_competitive_bid

        # If many opponents are still alive, ensure bid is sufficiently high
        if len(alive_opponents) > 1:
            my_bid = max(my_bid, DAILY_SALARY * 0.8)

    # Final checks: Ensure bid doesn't exceed budget and is at least 1.0
    final_bid = min(my_status['budget'], my_bid)
    final_bid = max(1.0, final_bid)

    return final_bid

